INSERT INTO `news` (`news_id`, `news_title`, `news_text`, `news_date`, `news_category_id`) VALUES
(1, 'Добро пожаловать!', 'Добро пожаловать на сайт обменного пункта!', '2020-10-15 00:00:00', 1),
(2, 'Вывод на банковскую карту любого банка Украины!', 'Уважаемые клиенты! С сегодняшнего дня в нашем обменном пункте открыт вывод с электронных кошельков Payeer на банковскую карту любого Украинского банка! Теперь Вы можете пополнить любую гривневую карту Visa/MasterCard. Приятных обменов!', '2020-10-15 01:00:00', 1),
(3, 'Обновление', 'Обновилась тема обменника', '2020-10-28 00:00:00', 1),
(4, 'Добавлены новые направления — вывод на карты Сбербанк RUB, АльфаБанк RUB ,Тинькофф RUB!', 'Уважаемые клиенты! Доступны новые направления обмена — вывод на рублевые карты Visa/MasterCard RUB, Сбербанк RUB, АльфаБанк RUB, Тинькофф RUB, ВТБ RUB с различных платежных систем! Приятных обменов!', '2020-10-30 00:00:00', 1),
(5, 'Правила проверки платежей Qiwi.', 'Вступил в силу новый регламент Qiwi. По некоторым платежам могут осуществляться проверки сроком до 48 часов. Результатом проверки может быть как успешное перечисление средств, так и их возврат обратно на счет. В случае, если средства в течение 48 часов не были зачислены на Ваш счет — обратитесь в нашу службу поддержки.\r\nПриятных обменов!', '2020-11-02 00:00:00', 1),
(6, 'Пополните счет букмекерской конторы PariMatch!', 'Уважаемые клиенты! Наш обменный пункт Myxa.cc расширил спектр услуг: теперь Вы можете пополнить счет в ведущей букмекерской конторе PariMatch c любой платежной системы. Пополнение без комиссии в гривне! Приятных обменов и удачных ставок!', '2020-11-03 10:00:00', 1),
(7, 'Обмены со счета мобильного телефона!', 'Приятная новость! Пользователи обменного пункта электронных валют Myxa.cc, могут пополнить cо счета мобильного телефона Киевстар и Vodafon электронные кошельки Qiwi, Payeer и др, а также карты Visa/MasterCard. Приятных обменов!', '2020-12-12 00:00:00', 1),
(8, 'Вывод на банковские карты Казахстана!', 'Уважаемые клиенты! Мы продолжаем расширять ассортимент направлений. Добавлен вывод на банковские карты Казахстана Visa/MasterCard KZT с популярных платежных систем и электронных кошельков! Воспользуйтесь новой услугой!', '2021-02-07 00:00:00', 1),
(9, 'Минимальные суммы обмена!', 'Уважаемые клиенты! На нашем сервисе Myxa.cc действуют минимальные суммы обмена, практически по всем направлениям. Спешите воспользоваться!', '2021-04-06 00:00:00', 1),
(10, 'Пополнение счета Slotoking и Pokermatch!', 'По многочисленным просьбам мы добавили новые услуги: теперь на Myxa.cc доступно 24/7 пополнение счета Slotoking и Pokermatch с удобной для вас платежной системы!\r\nПополнение в гривне — без комиссии, 1:1!\r\nУдачной игры!', '2021-06-10 00:00:00', 1),
(11, 'Новые направления обмена — вывод с рублевых карт Visa/MasterCard RUB и кошельков Qiwi!', 'Хорошая новость! Мы добавили новые направления обмена — вывод с рублевых карт Visa/MasterCard RUB и вывод с кошельков Qiwi rub на различные платежные системы и электронные кошельки! Приятных обменов!', '2021-08-04 00:00:00', 1),
(12, 'Мы на BestChange!', 'Приятная новость! Наш обменный пункт добавлен в листинг мониторинга BestChange. Приятных обменов!', '2021-10-11 00:00:00', 1),
(13, 'Сервис массовых выплат на карты!', 'Уважаемые клиенты! Массовые выплаты на банковские карты. Выплаты по реестру. Мы предлагаем гибкие варианты сотрудничества и формы пополнения баланса! Для получения более подробной информации о данной услуге напишите, пожалуйста, оператору в @telegram или онлайн-чат сайта.', '2022-01-18 00:00:00', 1),
(14, 'Оставь ОТЗЫВ — получи ПРИЗ!', 'ВНИМАНИЕ — ПРИЗ! Совершите обмен и оставьте отзыв о нас BestChange.ru. Среди 5 опубликованных отзывов \"прячется\" приз! Для публикации отзыва, перейдите по ссылке из полученного от BestChange письма на Вашей почте).', '2022-02-09 00:00:00', 1),
(15, 'Переводы на международные карты MasterCard EUR!', 'Уважаемые клиенты! Доступны переводы на международные карты MasterCard от 10 EUR! Лучшая конверсия и выгодный курс. Приглашаем к обмену!', '2022-08-06 00:00:00', 1),
(16, 'ВНИМАНИЕ! На данный момент доступен только обмен криптовалют на RUB/USD/UAH.', 'ВНИМАНИЕ! В связи с заменой платежной системы, на нашем сервисе, временно недоступно большинство способов обмена. На данный момент работает только обмен криптовалют на RUB/USD/UAH. Приносим извинения за неудобства. Следите за новостями.', '2022-09-08 00:00:00', 1);
