INSERT INTO `reviews` (`reviews_id`, `reviews_author`, `reviews_text`, `reviews_email`, `reviews_date`) VALUES
(1, 'Елена', 'Очень благодарю, Муха !!! Консультанты -супер, вот бы так все сервисы работали. Все объясняют, все помогают. Деньги пришли моментально. Спасибо!', '', '2022-10-25 15:10:00'),
(2, 'Алевтина', 'Спасибо за очередной обмен! Все быстро и четко!', '', '2022-10-24 18:10:00'),
(3, 'Ghost', 'Все быстро и четко. Спасибо', '', '2022-10-23 23:10:00'),
(4, 'Оксана', 'Все четко, быстро! Спасибо! Приятно работать с вами!', '', '2022-10-23 17:10:00'),
(5, 'Галина', 'Приятно иметь дело.быстро и надежно.рекомендую', '', '2022-10-22 14:10:00'),
(6, 'Raffael', 'Отличный обменник! Четкий, быстрый, а главное очень удобный! Буду и дальше работать с вами!))', '', '2022-10-22 14:10:00'),
(7, 'Алевтина', 'Меняла первый раз с TRC20 USDT на Сбер. Обмен прошел в течение 5 минут! Отлично! Буду пользоваться и рекомндовать.', '', '2022-10-20 14:10:00'),
(8, 'Оксана', 'Ребят! Вы сделали отличный сервис, который помогает людям в такой непростой ситуации! Огромная Вам за это благодарность! Процветания и успехов Вам и вашему бизнесу!', '', '2022-10-20 11:10:00'),
(9, 'Василий', 'Спасибо. Как всегда безупречно.', '', '2022-10-20 11:10:00'),
(10, 'Виктория', 'Какая прелесть автоматический обмен! Спасибо Myxa! Моментально прилетели денюжки!', '', '2022-10-19 17:10:00'),
(11, 'Андрей', 'Все работает отлично . Спасибо Большое ! ID 435836', '', '2022-10-19 15:10:00'),
(12, 'Дима', 'Супер', '', '2022-10-18 10:10:00'),
(13, 'Инна', 'Отправила сегодня деньги в Украину детям , второй раз!Перевод за считанные минуты. Всё супер здорово, очень удобно и быстро. Спасибо за, то, что вы с нами!', '', '2022-10-17 14:10:00'),
(14, 'Нина', '417177. Радость и удовлетворение вызывает моментальный обмен с карты на карту. Спасибо уважаемым сотрудникам Мухи.сс за слаженную работу!', '', '2022-10-17 13:10:00'),
(15, 'Viktoriya', 'Спасибо большое! Очень довольна! Рекомендую всем и каждому! Тут и сервис и скорость на высоте!!! Автоматически, и это важно!, прилетели денюжки на киви!', '', '2022-10-16 12:10:00'),
(16, 'Нина', 'Благодарю за быстрый обмен.', '', '2022-10-16 00:10:00'),
(17, 'Евгений', 'Все прошло успешно', '', '2022-10-15 22:10:00'),
(18, 'Геннадий', 'Отличный обменник. Рекомендую.', '', '2022-10-15 19:10:00'),
(19, 'Дмитрий', 'Вопросов по обмену, как обычно нет!)', '', '2022-10-15 15:10:00'),
(20, 'Игорь', 'Быстро! Супер! Автомат что надо.', '', '2022-10-15 12:10:00'),
(21, 'Виктор', 'Обмен прошёл замечательно все быстро даже несмотря на выходной. Всем советую!', '', '2022-10-15 10:10:00'),
(22, 'Виктория', 'Автоматически на киви! Супер! Написано рабочий день кончился, а денюжки моментально с USDT на киви прилетели. СПАСИБО!!!', '', '2022-10-14 20:10:00'),
(23, 'Viktoriya', 'Спасибо большое за автоматический обмен! Очень довольна! На киви моментально прилетели денюжки!', '', '2022-10-11 14:10:00'),
(24, 'Татьяна Леонидовна Гостищев', 'Благодарю за мгновенный обмен! Как всегда все на высшем уровне!.', '', '2022-10-11 12:10:00'),
(25, 'Елена', 'Нормальный курс, быстрый обмен. Рекомендую', '', '2022-10-10 09:10:00'),
(26, 'Ruslan', 'Сегодня 10.10.2022 07ч28м, обмен Сбербанка на Приват. Как всегда сервис на высшем уровне. Спасибо за Вашу роботу и за порядочность. Удачи всей команде!!!', '', '2022-10-10 07:10:00'),
(27, 'Viktoriya', 'Спасибо большое команде Myxa! Я Ваша фанатка уже. Очень довольна и нравится Ваш сервис. Рекомендую всем и каждому!', '', '2022-10-09 15:10:00'),
(28, 'Елена', 'Сервис нравиться. Рекомендую всем.', '', '2022-10-08 10:10:00'),
